function hexToRgb(hex: string): [number, number, number] {
  return [
    parseInt(hex.slice(1, 3), 16),
    parseInt(hex.slice(3, 5), 16),
    parseInt(hex.slice(5, 7), 16),
  ];
}

function samplePixels(
  canvas: HTMLCanvasElement,
  gap: number
): Array<{ x: number; y: number }> {
  const ctx = canvas.getContext("2d");
  if (!ctx) return [];

  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const pixels: Array<{ x: number; y: number }> = [];

  for (let y = 0; y < canvas.height; y += gap) {
    for (let x = 0; x < canvas.width; x += gap) {
      const i = (y * canvas.width + x) * 4;
      if (imageData.data[i + 3] > 128) {
        pixels.push({ x, y });
      }
    }
  }

  return pixels;
}

function renderLogoToCanvas(
  svgPaths: string[],
  svgViewBox: string,
  renderSize: number,
  renderMode: "fill" | "stroke",
  strokeWidth: number
): HTMLCanvasElement {
  const offscreen = document.createElement("canvas");
  offscreen.width = renderSize;
  offscreen.height = renderSize;
  const ctx = offscreen.getContext("2d")!;

  const [vx, vy, vw, vh] = svgViewBox.split(" ").map(Number);
  const scale = renderSize / Math.max(vw, vh);

  ctx.save();
  ctx.translate(-vx * scale, -vy * scale);
  ctx.scale(scale, scale);

  for (const d of svgPaths) {
    const path2d = new Path2D(d);
    if (renderMode === "stroke") {
      ctx.strokeStyle = "#000";
      ctx.lineWidth = strokeWidth;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.stroke(path2d);
    } else {
      ctx.fillStyle = "#000";
      ctx.fill(path2d);
    }
  }

  ctx.restore();
  return offscreen;
}

